"use client";import {FormEvent,useState} from "react";import type {Vehicle} from "@/lib/types";
export function InventoryManager({initial}:{initial:Vehicle[]}){const [items,setItems]=useState(initial);const [notice,setNotice]=useState("");async function save(e:FormEvent<HTMLFormElement>,id:string){e.preventDefault();setNotice("Saving…");const body=Object.fromEntries(new FormData(e.currentTarget));const response=await fetch(`/api/staff/vehicles/${id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const data=await response.json();if(response.ok){setItems(v=>v.map(x=>x.id===id?data:x));setNotice(`${data.title} saved and marketplace sync queued.`)}else setNotice(data.detail||"Could not save changes.")}return <><p role="status" className="notice">{notice}</p><div className="managerGrid">{items.map(v=><form className="panel manageCard" key={v.id} onSubmit={e=>save(e,v.id)}><div><span className={`status ${v.availability}`}>{v.availability}</span><h2>{v.title}</h2><small>Version {v.version} · {v.location}</small></div><label>Price (NGN)<input name="price" type="number" min="0" step="0.01" defaultValue={v.price}/></label><label>Website publication<select name="publication_status" defaultValue={v.publication_status}><option value="draft">Draft</option><option value="published">Published</option><option value="unpublished">Unpublished / withdrawn</option></select></label><label>Availability<select name="availability" defaultValue={v.availability}><option value="available">Available</option><option value="reserved">Reserved</option><option value="sold">Sold</option></select></label><button className="button">Save changes</button></form>)}</div></>}
